            Paragraph(Text("The original-minus-candidate difference uses the full externalT, including the identity pairing. The top theorem assumes boundary-eliminated difference equations explicitly. Deriving them from raw signed equations requires proving that the candidate negative-zero row and column equal the actual nonzero boundaries, then canceling them together with the same source terms. Evenness alone does not justify boundary elimination.")),
            Paragraph(Text("The conclusion gives one complex germ for each pair p,q. It supplies neither a common mode radius, a global identity, nor all signed sectors. It reuses the existing positive parity uniqueness theorem only after deriving both of its coefficient recurrences.")),
            Describe.Lean(DescribeId.Create("hasFPowerSeriesAt-euler-ofScalars"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalGermCoefficientBridge.hasFPowerSeriesAt_euler_ofScalars"), H("hasFPowerSeriesAt_euler_ofScalars"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A scalar series for the Euler derivative has coefficient n*a(n), including coefficient zero."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("analyticAt-eventually-zero-of-pos-real"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalGermCoefficientBridge.analyticAt_eventually_zero_of_pos_real"), H("analyticAt_eventually_zero_of_pos_real"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Zeros on a positive real interval force a complex analytic germ to vanish."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("linear-euler-germ-coefficients"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalGermCoefficientBridge.linear_euler_germ_coefficients"), H("linear_euler_germ_coefficients"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A linear Euler differential identity on a positive real interval determines its exact scalar Taylor coefficient equations."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("two-mul-radial-deriv-eq-euler"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalGermCoefficientBridge.two_mul_radial_deriv_eq_euler"), H("two_mul_radial_deriv_eq_euler"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The real radial derivative is converted to the complex Euler derivative at sqrt r for r positive."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("linear-radial-germ-coefficients"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalGermCoefficientBridge.linear_radial_germ_coefficients"), H("linear_radial_germ_coefficients"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Positive real radial identities imply z-Taylor recurrences after shrinking finitely many neighborhoods."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("externalT-positive-germ-unique-of-pos-real-differential"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalGermCoefficientBridge.externalT_positive_germ_unique_of_pos_real_differential"), H("externalT_positive_germ_unique_of_pos_real_differential"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Conditional positive-sector identification follows from explicitly boundary-eliminated difference equations and evenness, by deriving and reusing the parity coefficient induction."))), DescribeRole.Theorem))));
